files.referenceContent:
const TREE = {
  id: 'all',
  label: 'All permissions',
  children: [
    {
      id: 'repo',
      label: 'Repository',
      children: [
        { id: 'repo:read', label: 'Read code' },
        { id: 'repo:write', label: 'Push code' },
        { id: 'repo:admin', label: 'Change settings' },
      ],
    },
    {
      id: 'issues',
      label: 'Issues',
      children: [
        { id: 'issues:read', label: 'View issues' },
        { id: 'issues:write', label: 'Comment and close' },
      ],
    },
    { id: 'billing', label: 'Billing' },
  ],
};

const container = document.getElementById('tree');
const grantedOut = document.getElementById('granted');

/** Ids of the leaves that are currently granted. The only state there is. */
const granted = new Set(['repo:read']);

function isLeaf(node) {
  return !node.children || node.children.length === 0;
}

function leavesOf(node) {
  if (isLeaf(node)) return [node];
  return node.children.flatMap(leavesOf);
}

function stateOf(node) {
  const leaves = leavesOf(node);
  const on = leaves.filter((leaf) => granted.has(leaf.id)).length;
  if (on === 0) return 'off';
  if (on === leaves.length) return 'on';
  return 'partial';
}

function toggle(node, checked) {
  for (const leaf of leavesOf(node)) {
    if (checked) granted.add(leaf.id);
    else granted.delete(leaf.id);
  }
  render();
  updateSummary();
}

function nodeElement(node) {
  const li = document.createElement('li');
  const label = document.createElement('label');
  const box = document.createElement('input');
  box.type = 'checkbox';

  const state = stateOf(node);
  box.checked = state === 'on';
  box.indeterminate = state === 'partial';
  box.addEventListener('change', () => toggle(node, box.checked));

  const text = document.createElement('span');
  text.textContent = node.label;

  label.append(box, text);
  li.append(label);

  if (!isLeaf(node)) {
    const list = document.createElement('ul');
    for (const child of node.children) {
      list.append(nodeElement(child));
    }
    li.append(list);
  }
  return li;
}

function render() {
  container.textContent = '';
  const root = document.createElement('ul');
  root.append(nodeElement(TREE));
  container.append(root);
}

function updateSummary() {
  const names = leavesOf(TREE)
    .filter((leaf) => granted.has(leaf.id))
    .map((leaf) => leaf.label);
  grantedOut.textContent = names.length ? names.join(', ') : 'none';
}

render();
updateSummary();
